mapper.update:
CREATE INDEX ${tableName}_IDX1 ON ${tableName} (STATUS, REQDATE);
CREATE INDEX ${tableName}_IDX2 ON ${tableName} (PHONE);
CREATE INDEX ${tableName}_IDX3 ON ${tableName} (REQDATE, RSLT);
CREATE INDEX ${tableName}_IDX4 ON ${tableName} (IMG_GROUP_KEY);

CREATE INDEX ${tableName}_IDX1 ON ${tableName} (PHONE);
CREATE INDEX ${tableName}_IDX2 ON ${tableName} (REQDATE, RSLT);
CREATE INDEX ${tableName}_IDX3 ON ${tableName} (PRODUCT_CODE, RSLT);

UPDATE ${tableName}
SET
    STATUS = CASE WHEN STATUS = '3' THEN STATUS ELSE #{parameter.messageStatus} END
    , ROUTE_ID = #{parameter.routeId}
    , RSLT = #{parameter.doneCode}
    , RSLTDESC = #{parameter.doneCodeDescription}
    , RPTDATE = CONVERT(DATETIME,STUFF(STUFF(STUFF(#{parameter.doneDate},9,0,' '),12,0,':'),15,0,':'))
    , TELCO = #{parameter.doneTelco}
    , PRODUCT_CODE = #{parameter.doneProduct}
    , FALLBACK_REASON = #{parameter.doneFallbackCode}
    , FALLBACK_REASON_DESC = #{parameter.doneFallbackDetail}
WHERE
    MSGKEY IS NULL
    MSGKEY = #{parameter.key}

DELETE FROM ${tableName}
WHERE
    MSGKEY IS NULL
    MSGKEY = #{parameter.key}
